"""Compliance business case, with source scope and illustrative economics separated."""
def enrich_compliance(slides):
    url='https://8588479.fs1.hubspotusercontent-na1.net/hubfs/8588479/State%20of%20Trust%20Report%20-%20October%202025.pdf'
    slide=dict(label='THE COMPLIANCE TAX',title='Shipping is only half the job.<br><em>Then comes proving it.</em>',theme='co-pain',subtitle='',body='''<div class="co-columns"><div class="co-stat"><small>REPORTED COMPLIANCE WORKLOAD</small><strong>~10<span>hours / week</span></strong><p>Policy reviews. Evidence collection.<br>Vendor attestations.</p><div class="co-weeks"><b>12 working weeks a year</b><span>Vanta’s reported annual equivalent</span></div><p class="co-scope">Survey of business and IT leaders; not an engineering-only measure.</p></div><div class="co-solution"><small>OY ZU’S TARGET EXPERIENCE</small><h2>Evidence is a delivery output.</h2><div class="co-step"><b>01</b><div><strong>Define the required controls</strong><p>Versioned policy identifies required checks, approvals and evidence.</p></div></div><div class="co-step"><b>02</b><div><strong>Capture proof as work happens</strong><p>Bind actions, identities, results and attestations to the exact artifact.</p></div></div><div class="co-step"><b>03</b><div><strong>Retrieve the record when asked</strong><p>Trace source to deployment. Export control-linked evidence and expose gaps.</p></div></div></div></div><div class="co-bottom">Less reconstruction at audit time. <b>More traceability throughout delivery.</b></div>'''.replace('OY ZU','OYZU'),source=f'<a href="{url}">Vanta State of Trust, October 2025, pp. 14–15; methodology p. 24</a>. Vendor-commissioned survey; managed compliance workflow is Oyzu’s proposed experience.',notes='PDF methodology specifies 2,500 business and IT leaders across US, UK and Australia, surveyed July 2025 by Sapio Research for Vanta. Use this PDF sample, not the 3,500 figure from a different global press release. Pages14–15 describe teams spending approximately10 hours weekly on compliance and nearly12 working weeks annually. Broad compliance work, not audit preparation alone; not per-engineer or per-developer time. Do not multiply by engineering headcount. Target value: reduce manual reconstruction of software delivery evidence; no measured Oyzu reduction claimed. Control-linked exports and managed retention are proposed capabilities, not demonstrated production features. GRC platforms and auditors still own broader compliance assessment; automated technical evidence does not establish operating effectiveness of every organizational control.')
    slides.insert(10,slide)
    appendix=dict(label='APPENDIX · COMPLIANCE ECONOMICS',title='Price the work. <em>Measure the reduction.</em>',theme='co-economics ad-appendix',subtitle='',body='''<div class="co-money"><div><small>ILLUSTRATIVE ANNUAL EVIDENCE-PREPARATION LABOR</small><strong>$120,000</strong><p>10 contributors × 80 hours per audit cycle<br>× $150 loaded hourly cost × 1 cycle per year</p><span>Customer-validation model—not a survey result or Oyzu savings claim.</span></div><div class="co-costbars"><small>SENSITIVITY · SAME 10 PEOPLE AND $150 / HOUR</small><div><label>40 hours each</label><i style="width:25%"></i><b>$60K</b></div><div><label>80 hours each</label><i style="width:50%"></i><b>$120K</b></div><div><label>160 hours each</label><i style="width:100%"></i><b>$240K</b></div></div></div><div class="co-boundaries"><div><h3>Measure with design partners</h3><p>Engineering, platform and security hours spent locating records, reconciling gaps and answering requests. Compare the same audit scope before and after.</p></div><div><h3>Keep failure costs separate</h3><p>Remediation and reassessment can add expense; delayed customer approvals can affect revenue. No universal “failed audit” dollar figure is asserted.</p></div><div><h3>Complement the GRC stack</h3><p>Oyzu supplies technical delivery evidence. GRC tools and auditors assess broader controls, exceptions and effectiveness.</p></div></div>''',source=f'Illustrative inputs selected for sensitivity analysis; excludes auditor fees, tools and remediation. Research context: <a href="{url}">Vanta State of Trust 2025</a>.',notes='Formula contributors × preparation hours per contributor per cycle × loaded hourly cost × cycles per year. 10×40×150=60000;10×80×150=120000;10×160×150=240000. No inputs inferred from Vanta. Potential labor savings = measured hours avoided × relevant loaded cost; released capacity is not necessarily cash savings. Do not add delayed revenue to labor as if both were recurring software budget or TAM. No verified representative engineering-only audit workload or per-failed-audit cost obtained. Avoid the often quoted 2017 Ponemon noncompliance total as a cost per failed audit: scope and era differ. Public report has annual time equivalence; preserve its wording rather than infer workforce headcount. Evidence coverage, retention, identity assurance and unresolved exceptions remain explicit.')
    slides.insert(-1,appendix)
    return slides
